import{_ as l,l as o,o as e,c as n,v as t,p as s,x as r,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"尾延迟与对冲请求","description":"","frontmatter":{"title":"尾延迟与对冲请求","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tail-latency-hedging.md","filePath":"cs/tail-latency-hedging.md","lastUpdated":1789023840000}'),p={name:"cs/tail-latency-hedging.md"};function _(m,a,A,f,u,E){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="尾延迟与对冲请求" tabindex="-1">尾延迟与对冲请求 <a class="header-anchor" href="#尾延迟与对冲请求" aria-label="Permalink to &quot;尾延迟与对冲请求&quot;">​</a></h1><div class="epigraph"><p>一次用户请求扇出到许多后端，任一慢尾都会变成用户的 P99。对冲是再发一份，用多余负载换尾延迟，必须受预算约束。</p><footer>—— 据 Dean and Barroso, The Tail at Scale, CACM 2013 整理</footer></div><p>上一课<a href="/cs/timeout-backoff">超时退避</a>把重试放在失败之后。缺口是<strong>还没失败、只是慢</strong>：等超时才重试，用户已经付了长尾。Dean–Barroso 提出对冲：短等之后向另一副本再发。本课钉机制与放大风险。后课负载均衡决定第二份打到谁。完整「规模下的尾」在存储运维课序的 Tail at Scale 课还会从机房层再收一次，本课只接通信路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>扇出 \\(k\\) 路，独立尾延迟分布的最大值变差。队列、GC、磁盘、包丢都会造长尾。对冲：主请求发出后 \\(t_h\\) 仍无应答，复制一份到另一副本，谁先回用谁，取消另一份（若协议支持）。缺口：对冲在系统已过载时变成雪崩——人人发两份。</p><p>与幂等：对冲写等于并发双执行，必须<a href="/cs/idempotency-keys">幂等键</a>或只对读对冲。</p><p><span class="marginnote">CACM 2013 把对冲、备用、微分区、tail-tolerant 设计写在同一文。后课 <code>tail-at-scale</code> 从运维与机房再讲，本课不抢那层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>只对幂等读默认对冲。\\(t_h\\) 取历史延迟分位数（如 P95），不要 0（即双发打满）。对冲计入重试预算。取消要真能停下游工作，否则负载仍在。</p>',9)),(e(),s(h,null,{default:r(()=>[c(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20A%5B%22%E5%89%AF%E6%9C%AC%20A%22%5D%0A%20%20R%20--%3E%20W%5B%22%E7%AD%89%20t_h%22%5D%0A%20%20W%20--%3E%20B%5B%22%E5%89%AF%E6%9C%AC%20B%20%E5%AF%B9%E5%86%B2%22%5D%0A%20%20A%20--%3E%20WIN%5B%22%E5%85%88%E5%88%B0%E8%80%85%22%5D%0A%20%20B%20--%3E%20WIN%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与熔断：下游已开熔断不要对冲打另一实例同一过载池。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>负载放大：仅当慢尾触发，平均放大远小于 2。过载时人人变慢，\\(t_h\\) 总触发，放大趋近 2，正反馈。所以对冲要有全局预算与「仅健康实例」。这与<a href="/cs/rate-limit-circuit-breaker">限流</a>同一负反馈家族。</p><p>本课不把对冲写成金融对冲。也不写 WAN 任播的全部细节。</p><p>备份请求（hedged）与复制请求（同时双发）差别在 \\(t_h\\)。同时双发延迟更好、平时负载 ×2，只适合极热路径。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Google 内部的具体 \\(t_h\\) 数字当规范。后课默认：读路径才考虑对冲；写路径先幂等。负载均衡下一课决定副本选择，对冲是第二次选择。Tail at Scale 课把跨层排队再展开。</p><p>慢不等于死。把慢当死而无预算，检测器误伤会变成过载。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扇出放大尾延迟；对冲用第二份换 P99。</li><li>必须延迟触发、计入预算、优先只读。</li><li>过载时对冲变双发，要能自动关掉。</li><li>出处：Dean and Barroso, CACM 2013。</li></ul>',10))])}const g=l(p,[["render",_]]);export{T as __pageData,g as default};
